import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [n, m] = lines[0].split(" ").map(Number);
const graph: number[][] = Array.from({ length: n + 1 }, () => []);
const indegree = new Int32Array(n + 1);
for (let i = 1; i <= m; i++) {
  const [u, v] = lines[i].split(" ").map(Number);
  graph[u].push(v);
  indegree[v]++;
}

// 番号が小さい順に取り出す二分ヒープ
const heap: number[] = [];
function push(x: number): void {
  heap.push(x);
  for (let i = heap.length - 1; i > 0; ) {
    const p = (i - 1) >> 1;
    if (heap[p] <= heap[i]) break;
    [heap[p], heap[i]] = [heap[i], heap[p]];
    i = p;
  }
}
function pop(): number {
  const top = heap[0];
  const last = heap.pop()!;
  if (heap.length > 0) {
    heap[0] = last;
    for (let i = 0; ; ) {
      const l = 2 * i + 1;
      const r = l + 1;
      let min = i;
      if (l < heap.length && heap[l] < heap[min]) min = l;
      if (r < heap.length && heap[r] < heap[min]) min = r;
      if (min === i) break;
      [heap[min], heap[i]] = [heap[i], heap[min]];
      i = min;
    }
  }
  return top;
}

// 入ってくる辺がなくなった頂点のうち、最小の番号を毎回選ぶ
for (let v = 1; v <= n; v++) if (indegree[v] === 0) push(v);
const order: number[] = [];
while (heap.length > 0) {
  const v = pop();
  order.push(v);
  for (const next of graph[v]) {
    if (--indegree[next] === 0) push(next);
  }
}
console.log(order.length === n ? order.join(" ") : "-1");
